const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '细胞壁' },
      { kind: 'text', payload: '细胞核' },
      { kind: 'text', payload: '液泡' }
    ];
  },
  render: function (input, metrics) {
    var w = (input.viewport && input.viewport.widthDu) || 720;
    var h = (input.viewport && input.viewport.heightDu) || 520;
    function clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }
    function roundedRect(x, y, rw, rh, r) {
      r = Math.max(0, Math.min(r, Math.min(rw, rh) / 2));
      return [
        ['M', x + r, y],
        ['L', x + rw - r, y],
        ['C', x + rw - r + r * 0.552, y, x + rw, y + r - r * 0.552, x + rw, y + r],
        ['L', x + rw, y + rh - r],
        ['C', x + rw, y + rh - r + r * 0.552, x + rw - r + r * 0.552, y + rh, x + rw - r, y + rh],
        ['L', x + r, y + rh],
        ['C', x + r - r * 0.552, y + rh, x, y + rh - r + r * 0.552, x, y + rh - r],
        ['L', x, y + r],
        ['C', x, y + r - r * 0.552, x + r - r * 0.552, y, x + r, y],
        ['Z']
      ];
    }
    function smoothClosedPath(points) {
      var n = points.length;
      if (!n) return [];
      var cmds = [['M', points[0][0], points[0][1]]];
      for (var i = 0; i < n; i++) {
        var p0 = points[(i - 1 + n) % n];
        var p1 = points[i];
        var p2 = points[(i + 1) % n];
        var p3 = points[(i + 2) % n];
        cmds.push([
          'C',
          p1[0] + (p2[0] - p0[0]) / 6,
          p1[1] + (p2[1] - p0[1]) / 6,
          p2[0] - (p3[0] - p1[0]) / 6,
          p2[1] - (p3[1] - p1[1]) / 6,
          p2[0],
          p2[1]
        ]);
      }
      cmds.push(['Z']);
      return cmds;
    }
    function ellipsePoints(ex, ey, erx, ery, n) {
      var pts = [];
      for (var i = 0; i < n; i++) {
        var a = i / n * Math.PI * 2;
        pts.push([ex + Math.cos(a) * erx, ey + Math.sin(a) * ery]);
      }
      return pts;
    }
    function textSize(idx, text, fontSize) {
      var list = metrics;
      if (list && !Array.isArray(list)) {
        if (Array.isArray(list.items)) list = list.items;
        else if (Array.isArray(list.metrics)) list = list.metrics;
      }
      var m = list && list[idx];
      if (!m && list) {
        for (var q = 0; q < list.length; q++) {
          if (list[q] && (list[q].payload === text || list[q].text === text)) { m = list[q]; break; }
        }
      }
      var tw = m && (m.width || m.w);
      var th = m && (m.height || m.h);
      if (!tw) tw = text.length * fontSize * 0.98;
      if (!th) th = fontSize * 1.25;
      return { w: tw, h: th };
    }
    var fs = Math.max(14, Math.min(22, Math.min(w, h) * 0.036));
    var cx = w * 0.47;
    var cy = h * 0.52;
    var ry = Math.min(h * 0.36, w * 0.26);
    var rx = Math.min(w * 0.32, ry * 1.25);
    rx = Math.max(rx, 70);
    ry = Math.max(ry, 56);
    var vx = cx + rx * 0.04;
    var vy = cy + ry * 0.02;
    var vrx = rx * 0.52;
    var vry = ry * 0.55;
    var nx = cx - rx * 0.66;
    var ny = cy + ry * 0.46;
    var nr = Math.max(14, Math.min(rx, ry) * 0.20);
    var wallBand = Math.max(6, Math.min(rx, ry) * 0.04);
    var outerR = Math.min(rx, ry) * 0.22;
    var wallTx = cx - rx * 0.42;
    var wallTy = cy - ry - 2;
    var nucTx = nx + nr * 0.15;
    var nucTy = ny - nr * 0.05;
    var vacTx = vx + vrx * 0.88;
    var vacTy = vy - vry * 0.18;
    var sizeWall = textSize(0, '细胞壁', fs);
    var sizeNuc = textSize(1, '细胞核', fs);
    var sizeVac = textSize(2, '液泡', fs);
    var padX = 10;
    var padY = 6;
    function makeBox(x, y, size) {
      return { cx: x, cy: y, w: size.w + padX * 2, h: size.h + padY * 2, size: size };
    }
    var wallBox = makeBox(cx - rx * 0.55, cy - ry - Math.max(34, h * 0.07), sizeWall);
    wallBox.cx = clamp(wallBox.cx, wallBox.w / 2 + 10, w - wallBox.w / 2 - 10);
    wallBox.cy = clamp(wallBox.cy, wallBox.h / 2 + 10, h - wallBox.h / 2 - 10);
    var nucBox = makeBox(cx - rx - Math.max(50, w * 0.07), ny + nr * 0.2, sizeNuc);
    if (nucBox.cx - nucBox.w / 2 < 10) {
      nucBox.cx = nx;
      nucBox.cy = ny + nr + Math.max(24, h * 0.055);
    }
    nucBox.cx = clamp(nucBox.cx, nucBox.w / 2 + 10, w - nucBox.w / 2 - 10);
    nucBox.cy = clamp(nucBox.cy, nucBox.h / 2 + 10, h - nucBox.h / 2 - 10);
    var vacBox = makeBox(cx + rx + Math.max(50, w * 0.07), cy - ry * 0.12, sizeVac);
    if (vacBox.cx + vacBox.w / 2 > w - 10) {
      vacBox.cx = vx + vrx * 0.6;
      vacBox.cy = vy - vry - Math.max(24, h * 0.055);
    }
    vacBox.cx = clamp(vacBox.cx, vacBox.w / 2 + 10, w - vacBox.w / 2 - 10);
    vacBox.cy = clamp(vacBox.cy, vacBox.h / 2 + 10, h - vacBox.h / 2 - 10);
    function edgePoint(box, tx, ty) {
      var dx = tx - box.cx;
      var dy = ty - box.cy;
      if (Math.abs(dx) < 0.001 && Math.abs(dy) < 0.001) return { x: box.cx, y: box.cy };
      var hw = box.w / 2;
      var hh = box.h / 2;
      var sx = Math.abs(dx) < 0.001 ? Infinity : hw / Math.abs(dx);
      var sy = Math.abs(dy) < 0.001 ? Infinity : hh / Math.abs(dy);
      var s = Math.min(sx, sy);
      return { x: box.cx + dx * s, y: box.cy + dy * s };
    }
    var wallStart = edgePoint(wallBox, wallTx, wallTy);
    var nucStart = edgePoint(nucBox, nucTx, nucTy);
    var vacStart = edgePoint(vacBox, vacTx, vacTy);
    var paths = [];
    function addPath(id, commands) { paths.push({ id: id, commands: commands }); return id; }
    var wallOuterId = addPath('wallOuter', roundedRect(cx - rx, cy - ry, rx * 2, ry * 2, outerR));
    var wallInnerId = addPath('wallInner', roundedRect(cx - rx + wallBand, cy - ry + wallBand, (rx - wallBand) * 2, (ry - wallBand) * 2, Math.max(2, outerR - wallBand)));
    var membraneId = addPath('membrane', roundedRect(cx - rx + wallBand * 2, cy - ry + wallBand * 2, (rx - wallBand * 2) * 2, (ry - wallBand * 2) * 2, Math.max(2, outerR - wallBand * 2)));
    var vacPts = [];
    var nVac = 10;
    for (var i = 0; i < nVac; i++) {
      var a = i / nVac * Math.PI * 2;
      var f = 1 + 0.055 * Math.sin(i * 2.3 + 0.4) + 0.035 * Math.cos(i * 1.7);
      vacPts.push([vx + Math.cos(a) * vrx * f, vy + Math.sin(a) * vry * f]);
    }
    var vacId = addPath('vacuole', smoothClosedPath(vacPts));
    var hiPts = ellipsePoints(vx - vrx * 0.22, vy - vry * 0.30, vrx * 0.42, vry * 0.24, 8);
    var hiId = addPath('vacuoleHighlight', smoothClosedPath(hiPts));
    var nucId = addPath('nucleus', visualSdk.circle(nx, ny, nr));
    var envId = addPath('nuclearEnvelope', visualSdk.circle(nx, ny, nr * 0.78));
    var nucleolusId = addPath('nucleolus', visualSdk.circle(nx + nr * 0.12, ny - nr * 0.10, nr * 0.34));
    var chromatinDefs = [
      [nx - nr * 0.32, ny - nr * 0.18, nr * 0.07],
      [nx + nr * 0.22, ny + nr * 0.24, nr * 0.06],
      [nx - nr * 0.08, ny + nr * 0.46, nr * 0.05]
    ];
    var chromatinIds = [];
    for (i = 0; i < chromatinDefs.length; i++) {
      chromatinIds.push(addPath('chromatin' + i, visualSdk.circle(chromatinDefs[i][0], chromatinDefs[i][1], chromatinDefs[i][2])));
    }
    var lineWallId = addPath('lineWall', [['M', wallStart.x, wallStart.y], ['L', wallTx, wallTy]]);
    var lineNucId = addPath('lineNucleus', [['M', nucStart.x, nucStart.y], ['L', nucTx, nucTy]]);
    var lineVacId = addPath('lineVacuole', [['M', vacStart.x, vacStart.y], ['L', vacTx, vacTy]]);
    var dotWallId = addPath('dotWall', visualSdk.circle(wallTx, wallTy, 4.2));
    var dotNucId = addPath('dotNucleus', visualSdk.circle(nucTx, nucTy, 4.2));
    var dotVacId = addPath('dotVacuole', visualSdk.circle(vacTx, vacTy, 4.2));
    var bgWallId = addPath('bgWall', roundedRect(wallBox.cx - wallBox.w / 2, wallBox.cy - wallBox.h / 2, wallBox.w, wallBox.h, 8));
    var bgNucId = addPath('bgNucleus', roundedRect(nucBox.cx - nucBox.w / 2, nucBox.cy - nucBox.h / 2, nucBox.w, nucBox.h, 8));
    var bgVacId = addPath('bgVacuole', roundedRect(vacBox.cx - vacBox.w / 2, vacBox.cy - vacBox.h / 2, vacBox.w, vacBox.h, 8));
    var children = [];
    children.push({ type: 'path', pathId: wallOuterId, fill: '#e6f0d8', stroke: '#5d7f47', strokeWidth: 10, lineJoin: 'round' });
    children.push({ type: 'path', pathId: wallInnerId, fill: '#f6faef', stroke: '#a7c08e', strokeWidth: 2, lineJoin: 'round' });
    children.push({ type: 'path', pathId: membraneId, fill: 'none', stroke: '#b6cfa4', strokeWidth: 2, lineJoin: 'round' });
    children.push({ type: 'path', pathId: vacId, fill: '#cfe8f5', stroke: '#6fa6c4', strokeWidth: 3, lineJoin: 'round' });
    children.push({ type: 'path', pathId: hiId, fill: '#eaf7fc', opacity: 0.75 });
    children.push({ type: 'path', pathId: nucId, fill: '#f7dce8', stroke: '#b87394', strokeWidth: 3 });
    children.push({ type: 'path', pathId: envId, fill: 'none', stroke: '#d9a2bd', strokeWidth: 1.5 });
    children.push({ type: 'path', pathId: nucleolusId, fill: '#c96a91', stroke: '#a94f75', strokeWidth: 1.2 });
    for (i = 0; i < chromatinIds.length; i++) {
      children.push({ type: 'path', pathId: chromatinIds[i], fill: '#d99ab8', opacity: 0.9 });
    }
    children.push({ type: 'path', pathId: lineWallId, fill: 'none', stroke: '#5f6b58', strokeWidth: 1.8, lineCap: 'round' });
    children.push({ type: 'path', pathId: lineNucId, fill: 'none', stroke: '#5f6b58', strokeWidth: 1.8, lineCap: 'round' });
    children.push({ type: 'path', pathId: lineVacId, fill: 'none', stroke: '#5f6b58', strokeWidth: 1.8, lineCap: 'round' });
    children.push({ type: 'path', pathId: dotWallId, fill: '#5f6b58', stroke: '#ffffff', strokeWidth: 1.5 });
    children.push({ type: 'path', pathId: dotNucId, fill: '#5f6b58', stroke: '#ffffff', strokeWidth: 1.5 });
    children.push({ type: 'path', pathId: dotVacId, fill: '#5f6b58', stroke: '#ffffff', strokeWidth: 1.5 });
    children.push({ type: 'path', pathId: bgWallId, fill: '#ffffff', stroke: '#cfdcc5', strokeWidth: 1.2 });
    children.push({ type: 'path', pathId: bgNucId, fill: '#ffffff', stroke: '#cfdcc5', strokeWidth: 1.2 });
    children.push({ type: 'path', pathId: bgVacId, fill: '#ffffff', stroke: '#cfdcc5', strokeWidth: 1.2 });
    children.push({ type: 'label', x: wallBox.cx, y: wallBox.cy, text: '细胞壁', fontSize: fs, fill: '#2c3e2f', textAnchor: 'middle', dominantBaseline: 'middle', fontWeight: '600' });
    children.push({ type: 'label', x: nucBox.cx, y: nucBox.cy, text: '细胞核', fontSize: fs, fill: '#2c3e2f', textAnchor: 'middle', dominantBaseline: 'middle', fontWeight: '600' });
    children.push({ type: 'label', x: vacBox.cx, y: vacBox.cy, text: '液泡', fontSize: fs, fill: '#2c3e2f', textAnchor: 'middle', dominantBaseline: 'middle', fontWeight: '600' });
    return {
      schemaVersion: 1,
      sceneId: 'plant-cell-transcription',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
